/**
 * The headline numbers a probe measured for a variant on a class.
 */
export type VariantMeasured = {
    maxBatchSize?: number;
    predictsPerS?: number;
    predictP50Ms?: number;
    stepP50Ms?: number;
    vramBytes?: number;
    gpuModel?: string;
};

/**
 * What a probe found for one variant on one hardware class.
 */
export type VariantVerdict = {
    /**
     * Hardware class id
     */
    class: string;
    vendor?: 'nvidia' | 'amd' | 'cpu';
    product?: string;
    compute?: string;
    status: 'ready' | 'failed' | 'untested' | 'running';
    /**
     * The blocking check's detail on a failed class; prefixed "incompatible:" when the device was present but the image not built for it
     */
    reason?: string;
    /**
     * The probe run the verdict came from
     */
    runId?: string;
    cluster?: string;
    /**
     * One-line reading of the measurement: 16/batch · 420 predicts/s, step 0.5 ms
     */
    headline?: string;
    measured?: VariantMeasured;
    observedAt?: string;
    /**
     * Where a settled verdict came from: a probe run; a probe run of identical content (same layers, runtime config and rlmesh labels, same prober) on another version, which runId names; or an evaluation attempt that settled on the class (lower confidence; never overwrites a probe's)
     */
    source?: 'probe' | 'reused' | 'observed';
    queuedAt?: string;
};

/**
 * One compute variant of a version: the image that actually runs plus the facets and requirements that make it admissible on a hardware class.
 */
export type RepoVariant = {
    id: string;
    /**
     * Unique within the version, e.g. default, torch-cuda12, egl
     */
    key: string;
    /**
     * The pushed digest the variant belongs to
     */
    versionDigest: string;
    /**
     * The image that runs; the version itself for a single manifest, an index child's digest otherwise
     */
    imageDigest: string;
    source: 'index' | 'label' | 'profile' | 'synth' | 'manifest';
    /**
     * What the variant is built for: framework, accel, render
     */
    facets?: {
        [key: string]: unknown;
    };
    /**
     * What a class must offer: accel.vendor, accel.compute, accel.gfx, accel.cuda, accel.driver, accel.vram (a quantity like 16Gi)
     */
    requires?: {
        [key: string]: unknown;
    };
    /**
     * The owner's override of the declared requirements
     */
    requiresOverride?: {
        [key: string]: unknown;
    };
    /**
     * What a profile overlays on the shared image: envVars, gpu, resources
     */
    runtime?: {
        [key: string]: unknown;
    };
    priority: number;
    default: boolean;
    /**
     * excluded: never selected (a non-amd64 child); disabled: switched off by the owner
     */
    status: 'ready' | 'failed' | 'disabled' | 'excluded';
    /**
     * Per-image static report of a declared variant: checks[{name,status,detail}] plus the image's kind, platform{os,architecture,variant}, annotations, artifactType and the child's runtime declaration
     */
    static?: {
        [key: string]: unknown;
    };
    verdicts: Array<VariantVerdict>;
};

/**
 * One pushed version of a repo.
 */
export type RepoProbe = {
    digest: string;
    tag?: string;
    status: 'pending' | 'probing' | 'ready' | 'failed';
    message?: string;
    probedAt?: string;
    /**
     * The image's dev.rlmesh.describe envelope (detail responses only).
     */
    describe?: {
        [key: string]: unknown;
    };
    /**
     * The parsed dev.rlmesh.package payload.
     */
    package?: unknown;
    /**
     * Static label checks run at extraction time; any fail marks the probe failed.
     */
    static?: {
        checks: Array<{
            name: string;
            status: 'pass' | 'warn' | 'fail';
            detail: string;
        }>;
    };
    /**
     * Deprecated: read the per-class verdicts on variants instead.
     *
     * @deprecated
     */
    gpuSource?: 'explicit' | 'measured' | 'hinted' | 'prior';
    /**
     * @deprecated
     */
    gpu?: RepoProbeGpu;
    latestRun?: ProbeRunSummary;
    /**
     * The version's compute variants with the verdict each earned per hardware class.
     */
    variants?: Array<RepoVariant>;
};

export type Repo = {
    path: string;
    namespace: string;
    kind: 'model' | 'environment' | 'unknown';
    /**
     * Effective display name: edited displayName, else the package label's name, else the repo basename.
     */
    name: string;
    displayName?: string;
    description?: string;
    tags: Array<string>;
    /**
     * True for the platform-owned prebuilt namespace.
     */
    official: boolean;
    currentDigest?: string;
    /**
     * Channel push waiting to replace the current digest.
     */
    pendingDigest?: string;
    lastPush: RepoLastPush;
    /**
     * runnable whenever the current digest is ready (evaluations run it), whatever the last push is doing: lastPush and pendingDigest report a newer push still being checked or failed.
     */
    state: 'runnable' | 'checking' | 'failed' | 'not_current';
    probe?: RepoProbe;
    probes?: Array<RepoProbe>;
    /**
     * The current version's compute variants (detail responses only).
     */
    variants?: Array<RepoVariant>;
    /**
     * Key of the variant an unpinned evaluation runs.
     */
    defaultVariant?: string;
    updatedAt: string;
    /**
     * Set on an archived repo.
     */
    archivedAt?: string;
};

export type CompatibilityMatrix = {
    path: string;
    digest: string;
    /**
     * The version's effective readiness: ready on any class
     */
    status: 'pending' | 'probing' | 'ready' | 'failed';
    message?: string;
    classes: Array<{
        id: string;
        vendor: 'nvidia' | 'amd' | 'cpu';
        product: string;
        compute?: string;
        offered: boolean;
        provisional?: boolean;
    }>;
    variants: Array<{
        key: string;
        default: boolean;
        status: 'ready' | 'failed' | 'disabled' | 'excluded';
    }>;
    cells: Array<{
        variant: string;
        class: string;
        /**
         * untested: nothing has asked for the slot yet; scheduled: waiting in the probe queue; running: a probe is measuring it (runId names it); unsupported: the variant's requirements rule the class out before any probe
         */
        state: 'ready' | 'failed' | 'untested' | 'scheduled' | 'running' | 'unsupported';
        headline?: string;
        reason?: string;
        source?: 'probe' | 'reused' | 'observed';
        queuedAt?: string;
        runId?: string;
        cluster?: string;
        measured?: VariantMeasured;
        observedAt?: string;
    }>;
};

export type RepoVariantManifestEntry = {
    key: string;
    /**
     * One of the runnable images the version holds
     */
    imageDigest: string;
    facets?: VariantFacets;
    requires?: VariantRequires;
    runtime?: VariantRuntime;
    priority?: number;
    /**
     * Exactly one entry is the default
     */
    isDefault?: boolean;
    disabled?: boolean;
};

export type ProbeRun = {
    id: string;
    repo: string;
    digest: string;
    subject: 'model' | 'environment';
    status: 'queued' | 'running' | 'ready' | 'failed' | 'cancelled';
    cluster?: string;
    /**
     * Key of the compute variant the run measured; absent on runs from before variants were recorded
     */
    variant?: string;
    /**
     * Hardware class id the run measured on; absent until the run's hardware is known
     */
    class?: string;
    error?: string;
    flags: Array<ProbeFlag>;
    /**
     * The probe report the runner published, verbatim.
     */
    report?: unknown;
    recommendation?: ProbeRecommendation;
    hardware?: ProbeHardware;
    preview?: ProbePreview;
    createdAt: string;
    startedAt?: string;
    completedAt?: string;
};

export type RegistryRepository = {
    name: string;
    /**
     * The repo has more (unlinked) tags than the per-repo cap; the list is not exhaustive.
     */
    tagsTruncated?: boolean;
    tags: Array<{
        name: string;
        digest?: string;
        /**
         * Set when this tag's image is a child of an index version (a per-backend tag grouped by an OCI index); the version digest it belongs to.
         */
        indexDigest?: string;
        /**
         * The variant key the image has in the index version named by indexDigest.
         */
        variant?: string;
        entry?: {
            kind: 'model' | 'environment' | 'unknown';
            id: string;
            name: string;
            status?: 'pending' | 'probing' | 'ready' | 'failed';
            probe?: {
                [key: string]: unknown;
            };
        };
    }>;
};

